#!/usr/bin/env bash
# check_generated.sh — fails when the tracked generated Go code differs from what the
# pinned generators produce from the tracked .proto files (sdk.md S1, SDK-T1).
#
#   _scripts/check_generated.sh [repository_root]
#
# It generates into a temporary directory and compares the whole generated tree with the
# checkout: a changed or missing file fails, and so does any other file in the checkout
# that carries a protoc-gen-go "Code generated" header (an unexpected generated file,
# such as a stray second copy of the contract). It never writes into the checkout.
# A missing or wrongly versioned generator fails; there is no skip.
set -euo pipefail
repository_root="$(cd "${1:-$(dirname "$0")/..}" && pwd)"
scratch="$(mktemp -d)"
trap 'rm -rf "$scratch"' EXIT

"$repository_root/_scripts/generate.sh" "$scratch" >/dev/null || {
  echo "check_generated: generation failed" >&2
  exit 1
}

failed=0
expected_list="$scratch.expected"
actual_list="$scratch.actual"
trap 'rm -rf "$scratch" "$expected_list" "$actual_list"' EXIT
(cd "$scratch" && find . -type f | sed 's|^\./||' | LC_ALL=C sort) > "$expected_list"
(cd "$repository_root" && grep -rl --include='*.go' --exclude-dir=.git --exclude-dir=vendor \
  -E '^// Code generated by protoc-gen-go(-grpc)?\. DO NOT EDIT\.' . 2>/dev/null \
  | sed 's|^\./||' | LC_ALL=C sort) > "$actual_list" || true

while IFS= read -r file; do
  if [[ ! -f "$repository_root/$file" ]]; then
    echo "check_generated: missing generated file $file" >&2
    failed=1
  elif ! cmp -s "$scratch/$file" "$repository_root/$file"; then
    echo "check_generated: stale generated file $file (run: go generate ./contracts/...)" >&2
    failed=1
  fi
done < "$expected_list"

while IFS= read -r file; do
  if ! grep -qxF "$file" "$expected_list"; then
    echo "check_generated: unexpected generated file $file" >&2
    failed=1
  fi
done < "$actual_list"

if [[ $failed -ne 0 ]]; then
  exit 1
fi
echo "check_generated: generated code matches the contract"
